namespace jobs { void cancel(const unsigned int& id); }
void SoundFx::drive(Loop& l, bool on, Vec3 pos, Vec3 vel, f32 volume, f32 pitch, bool spatial, f32 max_distance) {
  if (!mixer_ || !l.clip) return;
  if (!on || volume < 0.002) {
    if (l.voice) { mixer_->stop(l.voice, 0.15); l.voice = 0; }
    return;
  }
  if (!l.voice || !mixer_->playing(l.voice)) {
    audio::PlayParams p;
    p.loop = true;
    p.volume = volume;
    p.pitch = pitch;
    p.spatial = spatial;
    p.position = pos;
    p.velocity = vel;
    p.min_distance = 3;
    p.max_distance = max_distance;
    p.bus = audio::Bus::sfx;
    p.fade_in = 0.1;
    l.voice = mixer_->play(l.clip, p);
    return;
  }
  mixer_->set_volume(l.voice, volume);
  mixer_->set_pitch(l.voice, clampf(pitch, 0.05, 8));
  if (spatial) mixer_->set_position(l.voice, pos, vel);
}
void SoundFx::update(const SoundState& s, f32 dt) {
  (void)dt;
  // Drone: SpawnCity mixes it at 50 % (audio_settings.mjs drone 50).
  drive(rotor_, s.drone.active, s.drone.position, s.drone.velocity, s.drone_mix * 0.5 * clampf(0.15 + s.drone.rate, 0, 1), 0.35 + 1.9 * s.drone.rate, true, 140);
  drive(prop_wash_, s.drone.active, s.drone.position, s.drone.velocity, s.drone_mix * 0.35 * s.drone.load, 0.7 + 0.6 * s.drone.rate, true, 90);
  // Vehicle 58 %.
  drive(engine_, s.car.active, s.car.position, s.car.velocity, s.vehicle_mix * 0.58 * (0.35 + 0.65 * s.car.load), 0.75 + 2.2 * s.car.rate, true, 120);
  drive(turbine_, s.jet.active, s.jet.position, s.jet.velocity, s.vehicle_mix * 0.45 * clampf(0.2 + s.jet.rate, 0, 1), 0.55 + 0.8 * s.jet.rate, true, 900);
  drive(roar_, s.jet.active, s.jet.position, s.jet.velocity, s.vehicle_mix * 0.9 * s.jet.load, 0.7 + 0.5 * s.jet.load, true, 1500);
  drive(siren_, s.siren.active, s.siren.position, s.siren.velocity, 0.42, 1.0, true, 260);
  drive(wind_, true, {}, {}, clampf((s.wind - 6) / 60, 0, 0.7), 0.8 + std::fmin(0.6, s.wind / 120), false, 0);
}
using audio::SynthPatch; namespace sound_fx_cpp_local { std::vector<f32> loop_of(std::initializer_list<SynthPatch> layers, u32 rate, f32 seconds) {
  std::vector<f32> out(converted::count(static_cast<std::size_t>(converted::fits<unsigned long>(seconds * rate))), 0.0);
  for (SynthPatch p : layers) {
    p.attack = 0.0;
    p.sustain = seconds + 0.25;
    p.release = 0.0;
    audio::mix_into(out, audio::synthesize(p, rate), 0, rate, 1);
  }
  out.resize(converted::count(static_cast<std::size_t>(converted::fits<unsigned long>(seconds * rate))));
  audio::make_seamless(out, rate, 0.12);
  audio::normalize(out, 0.8);
  return out;
} }
using audio::SynthPatch; using audio::Wave; bool SoundFx::init(Mixer& mixer) {
  mixer_ = &mixer;
  const u32 rate = mixer.sample_rate();
  if (!rate) return false;
  // Drone: motor whine at 140 Hz with its harmonics (saw through a resonant low-pass), the blade
  // pass at 100 Hz as a tremolo, prop wash as coloured noise.
  {
    SynthPatch motor;
    motor.wave = Wave::saw;
    motor.frequency = 140;
    motor.lowpass = 2600;
    motor.resonance = 0.35;
    motor.tremolo_depth = 0.45;
    motor.tremolo_rate = 100;
    motor.volume = 0.6;
    SynthPatch harm = motor;
    harm.wave = Wave::square;
    harm.frequency = 280;
    harm.duty = 0.3;
    harm.volume = 0.18;
    harm.lowpass = 3800;
    rotor_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({motor, harm}, rate, 1.0), 1, "spawncity:rotor", true);
    SynthPatch wash;
    wash.wave = Wave::pink;
    wash.lowpass = 1400;
    wash.highpass = 120;
    wash.volume = 0.5;
    wash.seed = 7;
    prop_wash_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({wash}, rate, 2.0), 1, "spawncity:propwash", true);
  }
  // Car: a four-cylinder at idle (firing 30 Hz) with crank harmonics; pitch follows revs.
  {
    SynthPatch base;
    base.wave = Wave::pulse;
    base.duty = 0.22;
    base.frequency = 55;
    base.lowpass = 900;
    base.resonance = 0.2;
    base.volume = 0.6;
    SynthPatch rumble;
    rumble.wave = Wave::sine;
    rumble.frequency = 27.5;
    rumble.volume = 0.45;
    SynthPatch intake;
    intake.wave = Wave::noise;
    intake.lowpass = 600;
    intake.volume = 0.12;
    intake.seed = 3;
    engine_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({base, rumble, intake}, rate, 1.0), 1, "spawncity:engine", true);
  }
  // Jet: turbine whine (two inharmonic sines) and the exhaust roar (low-passed pink noise).
  {
    SynthPatch whine;
    whine.wave = Wave::sine;
    whine.frequency = 1180;
    whine.vibrato_depth = 0.05;
    whine.vibrato_rate = 3;
    whine.volume = 0.35;
    SynthPatch whine2 = whine;
    whine2.frequency = 2240;
    whine2.volume = 0.15;
    turbine_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({whine, whine2}, rate, 1.0), 1, "spawncity:turbine", true);
    SynthPatch roar;
    roar.wave = Wave::pink;
    roar.lowpass = 700;
    roar.volume = 0.9;
    roar.seed = 11;
    SynthPatch crackle;
    crackle.wave = Wave::noise;
    crackle.lowpass = 2400;
    crackle.highpass = 900;
    crackle.volume = 0.12;
    crackle.seed = 13;
    roar_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({roar, crackle}, rate, 2.0), 1, "spawncity:roar", true);
  }
  {
    SynthPatch air;
    air.wave = Wave::pink;
    air.lowpass = 900;
    air.highpass = 60;
    air.volume = 0.6;
    air.seed = 21;
    wind_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({air}, rate, 3.0), 1, "spawncity:wind", true);
  }
  // Police siren: a wail sweeping 650..1450 Hz (two cycles in the 4 s loop) with a little grit.
  {
    SynthPatch wail;
    wail.wave = Wave::triangle;
    wail.frequency = 970;
    wail.vibrato_depth = 7;  // semitones: about 650 .. 1450 Hz
    wail.vibrato_rate = 0.5;
    wail.lowpass = 3200;
    wail.volume = 0.7;
    SynthPatch grit = wail;
    grit.wave = Wave::square;
    grit.duty = 0.5;
    grit.lowpass = 2200;
    grit.volume = 0.12;
    siren_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({wail, grit}, rate, 4.0), 1, "spawncity:siren", true);
  }
  return rotor_.clip && engine_.clip && turbine_.clip && roar_.clip && wind_.clip;
}
namespace touch_play_cpp_local { std::string esc(const std::string& s) {
  std::string o;
  for (char c : s) {
    if (static_cast<unsigned char>(c) < 0x20) { o += ' '; continue; }
    if (c == '"' || c == '\\') o += '\\';
    o += c;
  }
  return o;
} }
bool TouchPlay::sprint() const {
  const f32 m = std::min(1.0, hypot_bp(move_.x, move_.y));
  return m >= 0.90 && move_.y < -0.35;
}
std::string TouchPlay::view_json() const {
  if (lay_.mode == TouchMode::off) return "null";
  char buf[320];
  const f32 Ly = h_ - sb_ - kStick;
  const char* ml = lay_.mode == TouchMode::car ? "LENKEN / GAS" : lay_.mode == TouchMode::jet ? "STEIGEN / SCHUB" : "";
  const char* rl = lay_.mode == TouchMode::car ? "UMSCHAUEN" : lay_.mode == TouchMode::jet ? "KNÜPPEL" : "";
  // The overlay draws the knob at 50 + 31 k %; the drone's knob travels 42 % (control_semantics.mjs).
  const f32 kk = lay_.mode == TouchMode::drone ? 42.0 / 31.0 : 1.0;
  const bool aiming = no_sticks();
  auto stick = [&](f32 x, Vec2 k, bool live, bool accent, const char* label) {
    std::snprintf(buf, sizeof buf, "{\"x\":%.1f,\"y\":%.1f,\"size\":%.1f,\"kx\":%.3f,\"ky\":%.3f,\"live\":%s,\"accent\":%s,\"label\":\"%s\"}", static_cast<double>(aiming ? -9999.0 : x), static_cast<double>(Ly), static_cast<double>(kStick),
                  static_cast<double>(k.x * kk), static_cast<double>(k.y * kk), live ? "true" : "false", accent ? "true" : "false", label);
    return std::string(buf);
  };
  std::string s = "{\"move\":" + stick(sl_, move_, move_id_ >= 0, sprint() && lay_.mode == TouchMode::foot, ml);
  s += ",\"look\":" + stick(w_ - sr_ - right_inset() - kStick, look_, look_id_ >= 0, false, rl);
  s += ",\"buttons\":[";
  bool first = true;
  for (const TouchBtn& b : buttons_) {
    s += first ? "" : ",";
    first = false;
    s += "{\"id\":\"" + touch_play_cpp_local::esc(b.id) + "\",\"label\":\"" + touch_play_cpp_local::esc(b.label) + "\"";
    std::snprintf(buf, sizeof buf, ",\"x\":%.1f,\"y\":%.1f,\"w\":%.1f,\"h\":%.1f,\"round\":%s,\"pressed\":%s,\"on\":%s,\"color\":\"#%06x\"}", static_cast<double>(b.x), static_cast<double>(b.y), static_cast<double>(b.w), static_cast<double>(b.h), b.round ? "true" : "false",
                  b.pressed ? "true" : "false", b.on ? "true" : "false", b.color & 0xffffff);
    s += buf;
  }
  s += "]";
  if (!fires_.empty()) {
    std::snprintf(buf, sizeof buf, ",\"fire\":true,\"fireX\":%.1f,\"fireY\":%.1f", static_cast<double>(converted::back(fires_).x), static_cast<double>(converted::back(fires_).y));
    s += buf;
  }
  std::snprintf(buf, sizeof buf, ",\"mode\":%d,\"clearance\":%.3f", static_cast<int>(lay_.mode), static_cast<double>(clearance_));
  s += buf;
  return s + "}";
}
namespace touch_play_cpp_local { constexpr f32 kSafe = 10, kGap = 8; }
namespace touch_play_cpp_local { TouchBtn btn(const char* id, const std::string& label, f32 w, f32 h, u32 color, bool round, bool on_down = true) {
  TouchBtn b;
  b.id = id;
  b.label = label;
  b.w = w;
  b.h = h;
  b.color = color;
  b.round = round;
  b.on_down = on_down;
  return b;
} }
void TouchPlay::set_frame(f32 w, f32 h, f32 sl, f32 st, f32 sr, f32 sb) {
  w_ = w; h_ = h; sl_ = sl; st_ = st; sr_ = sr; sb_ = sb;
  layout();
}
void TouchPlay::place_row(std::vector<TouchBtn>& items, f32 x0, f32 bottom, f32 dir, f32 max_w) {
  // edge_hud_layout.mjs packRows: fill a row along dir, wrap upwards when it would exceed max_w.
  f32 x = x0, row_h = 0, y_bottom = bottom, used = 0;
  for (TouchBtn& b : items) {
    if (used > 0 && used + b.w > max_w) { y_bottom -= row_h + touch_play_cpp_local::kGap; x = x0; used = 0; row_h = 0; }
    b.x = dir > 0 ? x : x - b.w;
    b.y = y_bottom - b.h;
    x += dir * (b.w + touch_play_cpp_local::kGap);
    used += b.w + touch_play_cpp_local::kGap;
    row_h = std::max(row_h, b.h);
    add(b);
  }
}
void TouchPlay::layout() {
  // Keep the pressed state of buttons that stay.
  std::vector<std::string> down;
  for (const TouchBtn& b : buttons_)
    if (b.pressed) down.push_back(b.id);
  buttons_.clear();
  pad_w_ = pad_h_ = 0;
  if (lay_.mode == TouchMode::off) return;
  const TouchMode m = lay_.mode;
  // The sticks: 168 px flush in the safe corners (thumb_layout.mjs).
  const f32 Lx = sl_, Ly = h_ - sb_ - kStick, Rx = w_ - sr_ - right_inset() - kStick, Ry = h_ - sb_ - kStick;
  constexpr u32 dark = 0x0d1118, amber = 0x2a1d0c, blue = 0x0e2a3e, red = 0x8b2436, green = 0x2f9e5a, yellow = 0xffc93c;
  if (lay_.aiming) {
    // fighter_jets.mjs targeting overlay: tap the ground, or ABBRECHEN.
    TouchBtn c = touch_play_cpp_local::btn("strike_cancel", "✕ ABBRECHEN", 120, 40, red, false, false);
    c.x = (w_ - c.w) / 2;
    c.y = std::max(8.0, st_) + 60;
    add(c);
    return;
  }
  // ---- left thumb ----
  if (m == TouchMode::foot || m == TouchMode::car) {
    // the mode switch low, right of the move stick (game_exit_button.mjs: ⇄ DRONE / ⇄ FPS)
    TouchBtn mode = touch_play_cpp_local::btn("mode", m == TouchMode::foot ? (lay_.drone_cooldown ? "⇄ DRONE …" : "⇄ DRONE") : "⇄ FPS", 96, 40, m == TouchMode::foot ? 0x3a2810 : blue, false, false);
    mode.x = Lx + kStick + 8;
    mode.y = h_ - touch_play_cpp_local::kSafe - mode.h;
    add(mode);
  }
  std::vector<TouchBtn> left;
  if (m == TouchMode::foot) left.push_back(touch_play_cpp_local::btn("strike", "STRIKE", 58, 58, lay_.strike_ready ? dark : 0x3a3a3a, true));
  if (m == TouchMode::foot && lay_.grenade) {
    TouchBtn g = touch_play_cpp_local::btn("nade", lay_.grenade_left >= 0 ? (std::to_string(static_cast<int>(converted::fits<int>(lay_.grenade_left * 10)) / 10) + "." + std::to_string(static_cast<int>(converted::fits<int>(lay_.grenade_left * 10)) % 10)) : "● " + std::to_string(lay_.grenades), 64, 64,
                     lay_.grenade_left >= 0 ? 0x3a1c0c : 0x1c2414, true);
    g.on = lay_.grenade_left >= 0;
    left.push_back(g);
  }
  place_row(left, std::max(touch_play_cpp_local::kSafe, Lx + 10), Ly - 8, 1, std::max(kStick, 190.0));
  if (m == TouchMode::drone && !lay_.pad_drone) {
    // the altitude pad right of the move stick (simulator.mjs #soloClearance 48 x 132)
    TouchBtn p = touch_play_cpp_local::btn("clearance", "▲ HÖHE ▼", 48, 132, 0x101820, false);
    p.x = Lx + kStick + 8;
    p.y = h_ - touch_play_cpp_local::kSafe - p.h;
    pad_x_ = p.x; pad_y_ = p.y; pad_w_ = p.w; pad_h_ = p.h;
    add(p);
  }
  // ---- right thumb ----
  std::vector<TouchBtn> low;
  if (m == TouchMode::car) low.push_back(touch_play_cpp_local::btn("enter", "↗", 54, 54, 0xff6b5a, true, false));
  else if (m == TouchMode::drone) {
    // the drone of the small game: ARM and STOP under the thumb (no weapon, no mode switch - the areas that had them
    // are not in it); its camera is the button above the look stick
    if (!lay_.pad_drone) {
      low.push_back(touch_play_cpp_local::btn("arm", lay_.armed ? "ARMED" : "ARM", 104, 44, lay_.armed ? green : 0xf5b301, false, false));
      low.push_back(touch_play_cpp_local::btn("stop", "STOP", 94, 44, red, false, false));
    }
  } else if (m == TouchMode::foot) {
    low.push_back(touch_play_cpp_local::btn("wpn", "⇄ " + lay_.weapon, 60, 60, amber, true));
    low.push_back(touch_play_cpp_local::btn("jump", "JUMP", 64, 64, dark, true));
  }
  f32 x = Rx - 8;
  for (TouchBtn& b : low) {
    b.x = x - b.w;
    b.y = h_ - touch_play_cpp_local::kSafe - b.h;
    x -= b.w + 8;
    add(b);
  }
  if (m == TouchMode::foot && lay_.sniper) {
    // sniper_scope.mjs: SCOPE straight above the weapon button
    for (const TouchBtn& b : buttons_)
      if (b.id == "wpn") {
        TouchBtn s = touch_play_cpp_local::btn("scope", "◎ SCOPE", 60, 60, lay_.scope_on ? 0xb3261e : 0x0c1a14, true);
        s.on = lay_.scope_on;
        s.x = b.x;
        s.y = b.y - 66;
        add(s);
        break;
      }
  }
  if (m == TouchMode::car) {
    // #vehicleButtons: a column above the look stick, right aligned, gap 8
    TouchBtn cam = touch_play_cpp_local::btn("cam", lay_.cockpit ? "🎥 AUSSEN" : "🎥 INNEN", 104, 36, dark, false, false);
    TouchBtn hb = touch_play_cpp_local::btn("hb", "HANDBREMSE", 112, 36, dark, false);
    hb.x = w_ - touch_play_cpp_local::kSafe - hb.w;
    hb.y = Ry - 8 - hb.h;
    cam.x = w_ - touch_play_cpp_local::kSafe - cam.w;
    cam.y = hb.y - 8 - cam.h;
    add(cam);
    add(hb);
  } else if (m == TouchMode::drone) {
    // simulator.mjs #soloCamera: the next camera on a tap, its name on it - above the look stick, right aligned
    TouchBtn cam = touch_play_cpp_local::btn("cam", "🎥 " + lay_.camera, 104, 36, blue, false, false);
    cam.x = w_ - touch_play_cpp_local::kSafe - cam.w;
    cam.y = Ry - 8 - cam.h;
    add(cam);
  } else if (m == TouchMode::foot) {
    std::vector<TouchBtn> up;
    if (m == TouchMode::foot && lay_.near_car) up.push_back(touch_play_cpp_local::btn("enter", "🚗", 54, 54, yellow, true, false));
    if (m == TouchMode::foot && lay_.near_jet) up.push_back(touch_play_cpp_local::btn("jet", "✈", 54, 54, 0x7fd3ff, true, false));
    if (lay_.emp) up.push_back(touch_play_cpp_local::btn("emp", "EMP", 62, 36, 0x286eaa, false));
    place_row(up, w_ - touch_play_cpp_local::kSafe, Ry - 8, -1, std::max(kStick, 190.0));
  }
  if (m == TouchMode::jet) {
    // jet_mode.mjs: the buttons centred at the bottom, EJECT top left (hold), KANONE left of the look stick
    std::vector<TouchBtn> row = {touch_play_cpp_local::btn("vtol", lay_.hover ? "⇄ FLUG" : "⇄ SCHWEBEN", 96, 40, 0x08140c, false, false), touch_play_cpp_local::btn("rkt", "RAKETE", 72, 40, lay_.rocket ? 0x65400b : 0x08140c, false, false),
                                 touch_play_cpp_local::btn("bomb", "BOMBE", 70, 40, 0x08140c, false, false), touch_play_cpp_local::btn("cam", "CAM", 60, 40, 0x08140c, false, false)};
    converted::at(row, 1).on = lay_.rocket;
    f32 total = -8;
    for (const TouchBtn& b : row) total += b.w + 8;
    f32 bx = (w_ - total) / 2;
    for (TouchBtn& b : row) {
      b.x = bx;
      b.y = h_ - std::max(16.0, sb_) - b.h;
      bx += b.w + 8;
      add(b);
    }
    TouchBtn ej = touch_play_cpp_local::btn("eject", lay_.ground ? "AUSSTEIGEN" : "EJECT", 84, 38, 0x411811, false, false);
    ej.x = std::max(8.0, sl_);
    ej.y = st_ + 55;
    add(ej);
    const f32 size = clampf(w_ * 0.13, 96, 116);
    TouchBtn fire = touch_play_cpp_local::btn("fire", "KANONE", size, size, 0x7a1a12, true);
    fire.x = w_ - (std::max(12.0, sr_) + std::min(w_ * 0.25, 148.0) + 18) - size;
    fire.y = h_ - std::max(22.0, sb_ + 18) - size;
    add(fire);
  }
  for (TouchBtn& b : buttons_)
    if (std::find(down.begin(), down.end(), b.id) != down.end()) b.pressed = true;
  apply_dom_rects();
}
void TouchPlay::apply_dom_rects() {
  // The page draws the original's buttons (web/view.mjs, the original's DOM and CSS laid out by its
  // own edge_hud_layout.mjs / thumb_layout.mjs); a finger counts where the player sees the button.
  for (const DomRect& d : dom_) {
    if (d.id == "clearance") {
      // the height pad as drawn (#soloHeightPad): its axis centre and span, and where a finger
      // takes it - the button's own rectangle too (it kept the built-in one: a finger on the
      // visible DESCEND half missed it or landed on the stick beside it)
      if (pad_w_ > 0) { pad_x_ = d.x; pad_y_ = d.y; pad_w_ = d.w; pad_h_ = d.h; }
      for (TouchBtn& b : buttons_)
        if (b.id == "clearance") { b.x = d.x; b.y = d.y; b.w = d.w; b.h = d.h; }
      continue;
    }
    for (TouchBtn& b : buttons_)
      if (b.id == d.id) { b.x = d.x; b.y = d.y; b.w = d.w; b.h = d.h; }
  }
}
namespace terrain_cpp_local { u64 key2(i32 i, i32 j) { return (converted::shl_bits(static_cast<u64>(static_cast<u32>(i)), 32)) | static_cast<u32>(j); } }
f32 crater_profile(f32 r, f32 radius, f32 depth, f32 rim) {
  const f32 bowl = radius * 0.5;
  if (r < bowl) return -depth * (1 - (r / bowl) * (r / bowl));
  if (r >= radius) return 0;
  const f32 x = (r - bowl) / (radius - bowl), k = (x - 0.12) / 0.14;
  return rim * kern::math::exp(-(k * k)) * (1 - x);
}
namespace terrain_cpp_local { Vec4 interior_of(f32 x0, f32 y0, f32 span, f32 margin) { return {x0 + margin, y0 + margin, x0 + span - margin, y0 + span - margin}; } }
Vec4 Terrain::interior(const Grid& g) const {
  return terrain_cpp_local::interior_of(g.x0, g.y0, g.step * static_cast<f32>(g.n > 0 ? g.n - 1 : 0), kDemMargin);
}
f32 Terrain::grid_at(const Grid& g, f32 x, f32 y) const {
  if (g.n < 2) return 0;
  const f32 lim = static_cast<f32>(g.n) - 1.001;
  const f32 fx = clampf((x - g.x0) / g.step, 0, lim), fy = clampf((y - g.y0) / g.step, 0, lim);
  const u32 i = static_cast<u32>(converted::fits<unsigned int>(fx)), j = static_cast<u32>(converted::fits<unsigned int>(fy));
  const f32 tx = fx - i, ty = fy - j;
  const std::size_t at = converted::plus(converted::times(static_cast<std::size_t>(j), g.n), i);
  return (converted::at(g.h, at) * (1 - tx) + converted::at(g.h, converted::plus(at, 1)) * tx) * (1 - ty) + (converted::at(g.h, converted::plus(at, g.n)) * (1 - tx) + converted::at(g.h, converted::plus(converted::plus(at, g.n), 1)) * tx) * ty;
}
f32 Terrain::elevation(f32 x, f32 y) const {
  if (!grid_ready_) return 0.0;
  // the window that knows the place (its interior); else any that holds it; else the player's,
  // held at its edge (far ground nobody stands on: the horizon)
  auto in = [&](const Vec4& r) { return x >= r.x && y >= r.y && x <= r.z && y <= r.w; };
  if (side_.empty() || in(interior(grid_))) return grid_at(grid_, x, y) - ref_height_;
  for (const Grid& g : side_) if (in(interior(g))) return grid_at(g, x, y) - ref_height_;
  if (in(terrain_cpp_local::interior_of(grid_.x0, grid_.y0, grid_.step * static_cast<f32>(grid_.n - 1), 0))) return grid_at(grid_, x, y) - ref_height_;
  for (const Grid& g : side_) if (in(terrain_cpp_local::interior_of(g.x0, g.y0, g.step * static_cast<f32>(g.n - 1), 0))) return grid_at(g, x, y) - ref_height_;
  return grid_at(grid_, x, y) - ref_height_;
}
namespace terrain_cpp_local { constexpr f32 kRoadGrid = 24, kRoadBlend = 4.5; }
namespace terrain_cpp_local { u64 road_key(i32 ix, i32 iy) { return (converted::shl_bits(static_cast<u64>(static_cast<u32>(ix)), 32)) | static_cast<u32>(iy); } }
i32 Terrain::corridor_set(f32 x, f32 y) const {
  // the map tile whose square holds the point (the squares tile the plane: west / south edge in - one at most)
  for (std::size_t i = 0; i < corridors_.size(); converted::pre_inc(i)) {
    const CorridorSet& s = *converted::present(converted::at(corridors_, i));
    if (x >= s.bounds.x && x < s.bounds.z && y >= s.bounds.y && y < s.bounds.w) return static_cast<i32>(i);
  }
  return -1;
}
f32 Terrain::road_level(f32 x, f32 y, f32 h) const {
  // terrain_craters.mjs roadLevel: every corridor covering the point contributes (weighted), so
  // junctions blend smoothly, no steps
  const i32 at = corridors_.empty() ? -1 : corridor_set(x, y);
  if (at < 0) return h;
  const CorridorSet& set = *converted::present(converted::at(corridors_, static_cast<std::size_t>(at)));
  const auto it = set.grid.find(terrain_cpp_local::road_key(static_cast<i32>(converted::fits<int>(std::floor(x / terrain_cpp_local::kRoadGrid))), static_cast<i32>(converted::fits<int>(std::floor(y / terrain_cpp_local::kRoadGrid)))));
  if (it == set.grid.end()) return h;
  f32 best = 0, sw = 0, sh = 0;
  for (const CorridorSeg& s : it->second) {
    const f32 t = clampf(((x - s.ax) * s.dx + (y - s.ay) * s.dy) / s.l2, 0, 1);
    const f32 px = s.ax + s.dx * t, py = s.ay + s.dy * t, d = hypot_bp(x - px, y - py);
    const f32 w = d <= s.half ? 1 : d >= s.half + terrain_cpp_local::kRoadBlend ? 0 : 1 - (d - s.half) / terrain_cpp_local::kRoadBlend;
    if (w <= 0) continue;
    const f32 ws = w * w * (3 - 2 * w);
    sw += ws;
    sh += ws * (s.ha + (s.hb - s.ha) * t);
    best = std::fmax(best, w);
  }
  if (sw <= 0) return h;
  return h + (sh / sw - h) * (best * best * (3 - 2 * best));
}
f32 Terrain::node_height(f32 x, f32 y) const {
  const f32 e = elevation(x, y);
  f32 h = road_level(x, y, e);
  for (const Crater& c : craters_) {
    const f32 dx = x - c.c.x, dy = y - c.c.y;
    if (std::fabs(dx) >= c.r || std::fabs(dy) >= c.r) continue;
    const f32 r = kern::math::sqrt(dx * dx + dy * dy);
    if (r < c.r) h += crater_profile(r, c.r, c.depth, c.rim);
  }
  if (!water_.empty() && water_at(x, y)) return std::fmin(h, e - kWaterBed);
  return h;
}
f32 Terrain::height(f32 x, f32 y) const {
  // terrain_surface.mjs triangleHeightAt: the SW-NE diagonal of every 5 m cell.
  const f32 x0 = std::floor(x / kStep) * kStep, y0 = std::floor(y / kStep) * kStep;
  const f32 u = (x - x0) / kStep, v = (y - y0) / kStep;
  const f32 a = node_height(x0, y0), d = node_height(x0 + kStep, y0 + kStep);
  return u >= v ? a + (node_height(x0 + kStep, y0) - a) * (u - v) + (d - a) * v : a + (node_height(x0, y0 + kStep) - a) * (v - u) + (d - a) * u;
}
bool Terrain::water_cell(i32 cx, i32 cy) const {
  // the 256 bits of the cell's 64 m block
  auto it = water_.find(terrain_cpp_local::key2(cx >> 4, cy >> 4));
  if (it == water_.end()) return false;
  const u32 idx = static_cast<u32>(converted::plus(converted::times((cy & 15), 16), (cx & 15)));
  return (converted::shr_bits(converted::at(it->second.bits, idx >> 6), (idx & 63))) & 1u;
}
bool Terrain::on_bridge(f32 x, f32 y) const {
  for (const Bridge& b : bridges_) {
    const f32 dx = x - b.c.x, dy = y - b.c.y;
    if (std::fabs(dx) > b.hl + b.hw || std::fabs(dy) > b.hl + b.hw) continue;
    const f32 c = kern::math::cos(b.yaw), s = kern::math::sin(b.yaw), u = dx * c + dy * s, v = -dx * s + dy * c;
    if (std::fabs(u) <= b.hl && std::fabs(v) <= b.hw) return true;
  }
  return false;
}
bool Terrain::water_at(f32 x, f32 y) const {
  if (water_.empty()) return false;
  if (!water_cell(static_cast<i32>(converted::fits<int>(std::floor(x / kWaterCell))), static_cast<i32>(converted::fits<int>(std::floor(y / kWaterCell))))) return false;
  return bridges_.empty() || !on_bridge(x, y);
}
