  return (converted::shl_bits(static_cast<u64>(level), 56)) | (converted::shl_bits((static_cast<u64>(static_cast<u32>(i)) & 0xFFFFFFF), 28)) | (static_cast<u64>(static_cast<u32>(j)) & 0xFFFFFFF);
